INSERT INTO docs_distribution_request_item (
    request_id, line_no, document_line_no, file_line_no,
    object_type, object_id, file_no,
    material_no, material_name, original_file_name, file_size, grade_cd
) VALUES (
    #{requestId}, #{lineNo}, #{documentLineNo}, #{fileLineNo},
    #{objectType}, #{objectId}, #{fileNo},
    #{materialNo}, #{materialName}, #{originalFileName}, #{fileSize}, #{gradeCd}
)

INSERT INTO docs_distribution_request_recipient (
    request_id, line_no, partner_company_id, partner_user_id,
    user_name, email, phone, representative_yn
) VALUES (
    #{requestId}, #{lineNo}, #{partnerCompanyId}, #{partnerUserId},
    #{userName}, #{email}, #{phone}, #{representativeYn}
)

mapper.select:
SELECT 
  FROM docs_distribution_request request_row
 WHERE request_row.request_id = #{value}

SELECT 
  FROM docs_distribution_request request_row
 WHERE 1 = 1

   AND request_row.requested_by_user_cd = #{requestedByUserCd}


   AND request_row.approver_user_cd = #{approverUserCd}


   AND request_row.status = #{status}


   AND request_row.status = 'PENDING_APPROVAL'
   AND request_row.distribution_end_date >= CURRENT_DATE


   AND request_row.status = 'APPROVED'
   AND request_row.distribution_end_date >= CURRENT_DATE

 ORDER BY request_row.updated_at DESC, request_row.request_id DESC
 LIMIT #{limit} OFFSET #{offset}
